if(typeof require==='function'){var Classy=require('./classy');}var ArrayUtils=Classy.newClass();ArrayUtils.classMethods({shuffle:function(array){var currentIndex=array.length,temporaryValue,randomIndex;while(0!==currentIndex){randomIndex=Math.floor(Math.random()*currentIndex);currentIndex-=1;temporaryValue=array[currentIndex];array[currentIndex]=array[randomIndex];array[randomIndex]=temporaryValue;}return array;},unique:function(array){var seen={};var filtered=array.filter(function(item){return seen.hasOwnProperty(item)?false:(seen[item]=true);});array.length=0;for(var i in filtered){array.push(filtered[i]);}return array;},indexOf:function(array,item,comparisonFn){for(var i=0;i<array.length;++i){if(comparisonFn(array[i],item)){return i;}}return-1;},containsDuplicates:function(array){return new Set(array).size!=array.length;},containsSome:function(firstArray,secondArray){return secondArray.some(function(value){return firstArray.indexOf(value)>=0;});},containsAll:function(firstArray,secondArray){return secondArray.every(function(value){return firstArray.indexOf(value)>=0;});},containsSame:function(firstArray,secondArray){return ArrayUtils.containsAll(firstArray,secondArray)&&ArrayUtils.containsAll(secondArray,firstArray)}});if(typeof module==='object'){module.exports=ArrayUtils;}